window.addEventListener('DOMContentLoaded',()=>{'use strict';
const $=id=>document.getElementById(id),D=GlyphDesign,E=GlyphScene,F=GlyphFlow.model,C=GlyphFlow.core,catalog=D.catalog(),preview=$('preview'),behaviorStage=$('behavior-preview'),auth=window.GLYPH_BRIDGE,behaviorWorkspace=new GlyphFlow.Document(behaviorStage);
let selected='sphere',behavior='shell',view='objects',family='All',candidate=null,options=null,currentFlow=null,busy=false;
const report=value=>$('status').textContent=value.message||String(value);
async function api(route,body){if(!auth)throw Error('Open the local design library to apply a preset.');const r=await fetch('/api/'+route,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+auth.token,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})}),data=await r.json();if(!r.ok)throw Error(data.error?.message||'Request failed.');return data;}
function selectObject(id){selected=id;const o=D.preset('object',id);$('material').value=o.supportsFlow?'signal':'wire';$('content').value=o.supportsText?'OBSERVE / SIGNAL / ':'';$('content').disabled=!o.supportsText;$('content').placeholder=o.particles?'Particle trace / no text mapping':'Glyph texture / no text mapping';$('color').value='preset';$('float').checked=false;motionOptions(o.defaultMotion);listObjects();build();}
function motionOptions(selectedMotion=$('motion').value){const object=D.preset('object',selected);$('motion').replaceChildren(...catalog.motions.map(m=>{const option=new Option(m.name,m.id);option.disabled=m.requires==='path'&&!object.supportsFlow||m.channel==='glyph'&&object.particles;return option;}));$('motion').value=catalog.motions.some(m=>m.id===selectedMotion&&(!m.requires||object.supportsFlow)&&!(m.channel==='glyph'&&object.particles))?selectedMotion:object.defaultMotion;}
function listObjects(){const list=catalog.objects.filter(o=>family==='All'||o.family===family);$('object-list').replaceChildren(...list.map(o=>{const b=document.createElement('button');b.className='preset-card';b.setAttribute('aria-pressed',String(o.id===selected));b.setAttribute('aria-label',o.name+' object');const symbol=document.createElement('span'),name=document.createElement('strong'),tag=document.createElement('span');symbol.className='symbol';symbol.textContent=o.symbol;symbol.setAttribute('aria-hidden','true');name.textContent=o.name;tag.textContent=o.family.toUpperCase();b.append(symbol,name,tag);b.onclick=()=>selectObject(o.id);return b;}));}
function lock(){for(const b of document.querySelectorAll('[data-view],.preset-card,.behavior-card'))b.disabled=busy;for(const id of ['apply-preset','download','play-behavior'])$(id).disabled=busy||!candidate||(id==='apply-preset'&&(!auth||view==='behaviors'&&D.preset('behavior',behavior).target==='geometry'));}
function readOptions(){const duration=Number($('duration').value),seed=Number($('seed').value),motion=$('motion').value,ids=[motion];if(!$('seed').value||!Number.isInteger(seed))throw Error('Use a whole-number seed.');if(!$('duration').value)throw Error('Choose a loop duration.');$('float').disabled=motion==='still'||motion==='bob';if($('float').disabled)$('float').checked=false;if($('float').checked)ids.push('bob');return {object:selected,motions:ids,material:$('material').value,...($('color').value==='preset'?{}:{color:$('color').value}),text:$('content').value,seed,duration};}
function build(){try{const settings=readOptions(),next=D.scene(settings);options=settings;candidate=next;preview.scene=next;const item=D.preset('object',selected);$('content').disabled=!item.supportsText||options.motions.some(id=>D.preset('motion',id).channel==='glyph');$('preset-name').textContent=item.name;$('preset-description').textContent=item.description;$('preview-label').textContent=item.family.toUpperCase()+' / '+item.id.toUpperCase();$('api-example').textContent='const recipe = GlyphDesign.scene('+JSON.stringify(options,null,2)+');\nsceneElement.scene = recipe;\n// Add a new instance while preserving an existing composition:\nconst next = GlyphDesign.append(currentScene, options);';$('recipe').textContent=JSON.stringify(candidate,null,2);report('Preview only. '+options.motions.map(id=>D.preset('motion',id).name).join(' + ')+'.');lock();}catch(e){candidate=null;options=null;report(e);$('apply-preset').disabled=$('download').disabled=true;}}
preview.addEventListener('glyph-ready',e=>$('render-stats').textContent=e.detail.instances+' GLYPHS / '+e.detail.drawCalls+' DRAWS / '+e.detail.renderer.toUpperCase());preview.addEventListener('glyph-error',e=>report(e.detail));
function listBehaviors(){$('behavior-list').replaceChildren(...catalog.behaviors.map(p=>{const b=document.createElement('button');b.className='behavior-card';b.textContent=p.name;b.setAttribute('aria-pressed',String(p.id===behavior));const tag=document.createElement('span');tag.textContent=p.target;b.append(tag);b.onclick=()=>{behavior=p.id;listBehaviors();showBehavior();};return b;}));}
function showBehavior(){const p=D.preset('behavior',behavior),doc=C.json(F.defaultDocument()),n=doc.components[p.id==='hop-categorize'?1:0];doc.components=[n];doc.connections=[];doc.obstacles=[];n.position={x:0,y:0,width:100,height:100};n.title=p.name;n.spin=p.target==='interaction'?0:.18;if(n.id==='source'){n.initial=n.state=n.initial.slice(0,6);if(p.target==='layout'){Object.assign(n.layout,p.settings.layout);n.spin=p.settings.spin;}if(p.target==='interaction')n.methods.add.interaction=p.settings.interaction;}else n.methods.add.interaction=p.settings.interaction;n.layout.interactive=false;behaviorWorkspace.load(doc);if(p.target==='geometry'){const d=F.compileComponent(doc,n);behaviorStage.node(n.id).reorganize(d.organize,p.settings.motion);}candidate=p.settings;$('preview-label').textContent=p.target.toUpperCase()+' / '+p.id.toUpperCase();$('preset-name').textContent=p.name;$('preset-description').textContent=p.description;$('render-stats').textContent='LOCAL COMPONENT PREVIEW';$('api-example').textContent=p.target==='layout'?'workspace.configureLayout(componentId, '+JSON.stringify(p.settings.layout,null,2)+');':p.target==='interaction'?'// Set the receiving method’s interaction, preserving its contracts and handler.\nmethod.interaction = '+JSON.stringify(p.settings.interaction,null,2)+';':'node.reorganize(organize, '+JSON.stringify(p.settings.motion)+');\nnode.dispatch("shuffle", {seed:23});';$('recipe').textContent=JSON.stringify(p.settings,null,2);$('method-label').hidden=p.target!=='interaction';$('behavior-destination').hidden=p.target==='geometry';$('play-behavior').textContent=p.target==='interaction'?'Send a sample word ↗':'Reorganize preview ↻';$('apply-preset').textContent=p.target==='geometry'?'Use the programmer API below':'Apply behavior to component ↗';$('download').textContent='Download preset ↓';$('application-note').textContent=p.target==='geometry'?'Geometry presets are local programmer hooks. Preview them here or use the API below.':'Applying changes the selected component’s settings and preserves its data and method contracts.';methodOptions();lock();report('Preview only. Choose a target before applying.');}
function methodOptions(){const n=currentFlow?.flow.components.find(n=>n.id===$('target-component').value),old=$('target-method').value;$('target-method').replaceChildren(...Object.keys(n?.methods||{}).map(id=>new Option(id,id)));if(n?.methods[old])$('target-method').value=old;}
async function destinations(){if(!auth)return;try{currentFlow=await api('flow');const old=$('target-component').value;$('target-component').replaceChildren(...currentFlow.flow.components.map(n=>new Option(n.title+' / '+n.id,n.id)));if(currentFlow.flow.components.some(n=>n.id===old))$('target-component').value=old;methodOptions();}catch(e){report(e);}}
$('target-component').onchange=methodOptions;
$('play-behavior').onclick=async()=>{if(busy)return;busy=true;showBehavior();lock();const p=D.preset('behavior',behavior),n=behaviorStage.nodes[0];try{if(p.target==='interaction'){const row={id:'preview-word',title:'SIGNAL',category:'SIGNAL'};await n.invoke('add',n.id==='cluster'?[row]:row);report('Sample received. The component committed its intact record.');}else{n.dispatch('shuffle',{seed:23});report('The local array changed order. No transport packet was created.');}}catch(e){report(e);}finally{busy=false;lock();}};
$('apply-preset').onclick=async()=>{if(busy||!candidate)return;const chosenOptions=options?JSON.parse(JSON.stringify(options)):null,chosenPreset=behavior,chosenComponent=$('target-component').value,chosenMethod=$('target-method').value;busy=true;lock();try{if(view==='objects'){const saved=await api('state'),scene=D.append(saved.scene,chosenOptions),result=await api('tool',{name:'glyph_studio_apply',arguments:{scene,expected_revision:saved.revision}});report('Added '+D.preset('object',chosenOptions.object).name+' to the current scene. Saved revision '+result.revision+'.');}else{const saved=await api('flow'),p=D.preset('behavior',chosenPreset),component=chosenComponent,n=saved.flow.components.find(n=>n.id===component);if(!n)throw Error('Choose an existing component.');let changes;if(p.target==='layout')changes=p.settings;else{const method=chosenMethod;if(!n.methods[method])throw Error('Choose an existing receiving method.');changes={methods:{[method]:{interaction:p.settings.interaction}}};}const result=await api('tool',{name:'glyph_flow_edit',arguments:{action:'update',kind:'component',id:component,changes_json:JSON.stringify(changes),expected_revision:saved.revision}});report('Applied '+p.name+' to '+component+'. Saved revision '+result.revision+'.');await destinations();}}catch(e){report(e);}finally{busy=false;lock();}};
$('download').onclick=()=>{const blob=new Blob([JSON.stringify(candidate,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=view==='objects'?selected+'.scene.json':behavior+'.preset.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('pause').onclick=()=>{const stage=view==='objects'?preview:behaviorStage,paused=stage.toggleAttribute('paused');$('pause').textContent=paused?'Play':'Pause';};$('restart').onclick=()=>{if(view==='objects')preview.seek(0);else showBehavior();};
for(const id of ['motion','material','color','duration','seed','content','float'])$(id).onchange=()=>{if(id==='motion'&&D.preset('motion',$('motion').value).channel==='glyph'&&$('material').value==='wire'){$('material').value='matrix';$('color').value='preset';$('content').value='';}if(id==='material'){$('content').value=D.preset('object',selected).supportsText?D.preset('material',$('material').value).glyphs.text:'';$('color').value='preset';}build();};
for(const familyName of ['All','Surface','Path','Composite']){const b=document.createElement('button');b.textContent=familyName;b.setAttribute('aria-pressed',String(familyName===family));b.onclick=()=>{family=familyName;for(const button of $('families').children)button.setAttribute('aria-pressed',String(button===b));listObjects();};$('families').append(b);}
$('material').replaceChildren(...catalog.materials.map(m=>new Option(m.name,m.id)));for(const id of [...Object.keys(catalog.tokens.colors),'rainbow'])$('color').append(new Option(id,id));
function swatches(id,values){$(id).replaceChildren(...Object.entries(values).map(([name,color])=>{const el=document.createElement('div'),swatch=document.createElement('i'),label=document.createElement('strong');el.className='swatch';swatch.style.background=color;label.textContent=name;el.append(swatch,label,document.createTextNode(color));return el;}));}
swatches('color-tokens',catalog.tokens.colors);swatches('interface-tokens',Object.fromEntries(['background','surface','ink','muted','line','accent'].map(k=>[k,catalog.tokens[k]])));const rhythm=document.createElement('div');rhythm.className='rhythm';for(const [name,seconds] of Object.entries(catalog.tokens.timing)){const item=document.createElement('span');item.textContent=name+' / '+seconds+'s';rhythm.append(item);}const spaces=document.createElement('div');spaces.className='space-sample';for(const size of catalog.tokens.space){const item=document.createElement('span');item.style.height=size+'px';item.style.minWidth=size+'px';item.textContent=size;spaces.append(item);}$('rhythm-tokens').append(rhythm,spaces);$('tokens-code').textContent='// Optional preset module; rendered scenes need only the player.\nconst tokens = GlyphDesign.tokens;\n// CSS variables are generated from the same token object.\ncolor: var(--glyph-accent);\npadding: var(--glyph-space-16);';
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>{view=b.dataset.view;for(const tab of document.querySelectorAll('[data-view]'))tab.setAttribute('aria-pressed',String(tab===b));$('composition').hidden=view==='tokens';$('foundations').hidden=view!=='tokens';$('object-library').hidden=view!=='objects';$('behavior-library').hidden=view!=='behaviors';preview.hidden=view!=='objects';behaviorStage.hidden=view!=='behaviors';$('object-controls').hidden=view!=='objects';$('behavior-controls').hidden=view!=='behaviors';if(view==='behaviors'){showBehavior();destinations();}else if(view==='objects'){$('apply-preset').textContent='Add object to current scene ↗';$('download').textContent='Download recipe ↓';$('application-note').textContent='Preview changes stay here until you add them.';build();}$('pause').textContent=(view==='objects'?preview:behaviorStage).hasAttribute('paused')?'Play':'Pause';};
async function customLibrary(){if(!auth||!$('custom-library-list'))return;try{const [d,code,typed]=await Promise.all([api('presets'),api('programs'),api('typescript')]);$('custom-library-list').replaceChildren(...[...d.presets,...code.presets,...typed.presets].map(p=>{const a=document.createElement('a');a.href=p.kind==='typescript-component'?'/math#language':p.kind==='program'?'/math':'/presets';a.textContent=p.name+' / '+p.kind+' ↗';a.style.cssText='display:inline-block;margin:8px 20px 8px 0;color:#86d6ee';return a;}));}catch{}}
listBehaviors();selectObject('sphere');destinations();customLibrary();window.addEventListener('focus',customLibrary);
});
